const STATION: u16 = 1;

/// Keeps the security events it receives.
#[derive(Default)]
struct Recorder(Mutex<Vec<SecurityEvent>>);

impl Recorder {
    fn seen(&self) -> Vec<SecurityEvent> {
        self.0
            .lock()
            .map(|events| events.clone())
            .unwrap_or_default()
    }
}

impl SecurityEvents for Recorder {
    fn raise(&self, event: SecurityEvent, _detail: &str) {
        if let Ok(mut events) = self.0.lock() {
            events.push(event);
        }
    }
}

/// Gives a raw client the test client certificate: the station requires one (clause 6.4.3).
fn with_client_identity(builder: &mut openssl::ssl::SslConnectorBuilder) {
    let certificate = X509::from_pem(CLIENT_CERTIFICATE).expect("the client certificate");
    let key = openssl::pkey::PKey::private_key_from_pem(CLIENT_KEY).expect("the client key");
    builder
        .set_certificate(&certificate)
        .expect("the certificate");
    builder.set_private_key(&key).expect("the key");
}

/// The DER of every PEM certificate in `pem`.
fn der_list(pem: &[u8]) -> Vec<Vec<u8>> {
    X509::stack_from_pem(pem)
        .expect("certificates")
        .iter()
        .map(|certificate| certificate.to_der().expect("DER"))
        .collect()
}

/// The DER of a PEM file with one certificate, and of its key.
fn der_pair(certificate: &[u8], key: &[u8]) -> (Vec<Vec<u8>>, Vec<u8>) {
    let chain = der_list(certificate);
    let key = openssl::pkey::PKey::private_key_from_pem(key)
        .expect("a key")
        .private_key_to_der()
        .expect("DER of the key");
    (chain, key)
}

/// The OpenSSL backend of one station, with its identity, the five test roots, the CRLs, and the
/// TLS 1.3 switch.
fn backend(
    events: &Arc<Recorder>,
    certificate: &[u8],
    key: &[u8],
    crls: Vec<Vec<u8>>,
    tls13: bool,
) -> Secure {
    let (chain, key) = der_pair(certificate, key);
    let shared: Arc<dyn SecurityEvents> = events.clone();
    let identity = Identity::new(chain, key, events.as_ref()).expect("the identity");
    let trust = TrustAnchors::new(der_list(ROOTS)).expect("the roots");
    let settings = TlsSettings::new(identity, trust, shared)
        .with_revocation(crls)
        .with_tls13(tls13);
    Secure::new(OpensslBackend::new(&settings).expect("the backend"))
}

fn crl() -> Vec<Vec<u8>> {
    der_list_crl(CRL)
}

fn der_list_crl(pem: &[u8]) -> Vec<Vec<u8>> {
    let crl = openssl::x509::X509Crl::from_pem(pem).expect("a CRL");
    vec![crl.to_der().expect("DER")]
}

/// A handler that refuses every command: these tests only interrogate.
struct Refuse;

impl Handler for Refuse {
    fn select(&self, _operation: &Operation) -> Result<(), Refusal> {
        Err(Refusal::Rejected)
    }

    fn execute(&self, _operation: &Operation) -> Result<(), Refusal> {
        Err(Refusal::Rejected)
    }
}

/// Starts a station with one single-point, and returns its address.
async fn start_station(events: &Arc<Recorder>, tls13: bool) -> SocketAddr {
    let config = ServerConfig::new(
        "127.0.0.1:0".parse().expect("an address"),
        CommonAddress::new(STATION),
    )
    .with_tls(backend(
        events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        crl(),
        tls13,
    ));
    let server = Server::bind(config, Refuse)
        .await
        .expect("the station binds");
    let local = server.local_addr().expect("it has an address");
    let handle: ServerHandle = server.handle();
    let value = PointValue::Single(Siq {
        on: true,
        quality: QualityFlags::default(),
    });
    handle
        .add_point(
            InformationObjectAddress::new(1).expect("in range"),
            value,
            false,
        )
        .expect("the point");
    tokio::spawn(server.run());
    local
}

/// Waits, for at most 10 s, for the first event that `wanted` accepts.
async fn next_until(
    client: &mut Client,
    mut wanted: impl FnMut(&Event) -> bool,
    what: &str,
) -> Event {
    timeout(Duration::from_secs(10), async {
        loop {
            let event = client.next_event().await.expect("the client runs");
            if wanted(&event) {
                return event;
            }
        }
    })
    .await
    .unwrap_or_else(|_| panic!("no {what} within 10 s"))
}

/// Connects a TLS client to the station, and starts the data transfer.
async fn connect(address: SocketAddr, backend: Secure) -> Client {
    let config =
        ClientConfig::new(address, CommonAddress::new(STATION)).with_tls(backend, "localhost");
    let mut client = Client::connect(config);
    next_until(
        &mut client,
        |e| matches!(e, Event::Connected),
        "the connection",
    )
    .await;
    client.start_data_transfer().await.expect("the client runs");
    next_until(
        &mut client,
        |e| {
            matches!(
                e,
                Event::Delivery(Delivery::Transfer(TransferState::Started))
            )
        },
        "the start",
    )
    .await;
    client
}

/// Polls a recorder until it holds `wanted`, for at most 5 s.
async fn raised(events: &Recorder, wanted: SecurityEvent) -> bool {
    timeout(Duration::from_secs(5), async {
        loop {
            if events.seen().contains(&wanted) {
                return true;
            }
            sleep(Duration::from_millis(10)).await;
        }
    })
    .await
    .unwrap_or(false)
}

/// A raw OpenSSL client, offering only what the test sets, with the test roots. It returns the
/// standard name of the suite that was negotiated, or the error of the handshake.
async fn raw_client(
    address: SocketAddr,
    configure: impl FnOnce(&mut openssl::ssl::SslConnectorBuilder),
) -> Result<(String, Option<String>), String> {
    let mut builder = SslConnector::builder(SslMethod::tls_client()).map_err(|e| e.to_string())?;
    let mut store = X509StoreBuilder::new().map_err(|e| e.to_string())?;
    for root in X509::stack_from_pem(ROOTS).map_err(|e| e.to_string())? {
        store.add_cert(root).map_err(|e| e.to_string())?;
    }
    builder
        .set_verify_cert_store(store.build())
        .map_err(|e| e.to_string())?;
    builder.set_verify(SslVerifyMode::PEER);
    configure(&mut builder);
    let connector = builder.build();
    let ssl: Ssl = connector
        .configure()
        .map_err(|e| e.to_string())?
        .into_ssl("localhost")
        .map_err(|e| e.to_string())?;
    let tcp = TcpStream::connect(address)
        .await
        .map_err(|e| e.to_string())?;
    let mut stream = SslStream::new(ssl, tcp).map_err(|e| e.to_string())?;
    Pin::new(&mut stream)
        .connect()
        .await
        .map_err(|e| e.to_string())?;
    let cipher = stream.ssl().current_cipher().expect("a cipher");
    Ok((
        cipher.standard_name().unwrap_or_default().to_string(),
        Some(cipher.version().to_string()),
    ))
}

#[tokio::test]
async fn the_station_answers_an_interrogation_over_tls_13_and_raises_the_notice() {
    let server_events = Arc::new(Recorder::default());
    let client_events = Arc::new(Recorder::default());
    let station = start_station(&server_events, true).await;

    let mut client = connect(
        station,
        backend(&client_events, CLIENT_CERTIFICATE, CLIENT_KEY, crl(), true),
    )
    .await;
    client
        .interrogate(Qoi::STATION)
        .await
        .expect("the client runs");
    next_until(
        &mut client,
        |e| {
            matches!(e, Event::Delivery(Delivery::Asdu(asdu))
                if asdu.cot.cause() == cause::INTERROGATED_STATION
                    && matches!(asdu.body, Body::M_SP_NA_1(_)))
        },
        "the answer with the point",
    )
    .await;
    assert!(client_events
        .seen()
        .contains(&SecurityEvent::TlsHandshakeSuccess));
    assert!(raised(&server_events, SecurityEvent::TlsHandshakeSuccess).await);
}

#[tokio::test]
async fn the_station_answers_over_tls_12_when_tls_13_is_disabled() {
    let server_events = Arc::new(Recorder::default());
    let client_events = Arc::new(Recorder::default());
    let station = start_station(&server_events, false).await;

    let mut client = connect(
        station,
        backend(&client_events, CLIENT_CERTIFICATE, CLIENT_KEY, crl(), false),
    )
    .await;
    client
        .interrogate(Qoi::STATION)
        .await
        .expect("the client runs");
    next_until(
        &mut client,
        |e| matches!(e, Event::Delivery(Delivery::Asdu(asdu)) if asdu.cot.cause() == cause::ACTIVATION_TERMINATION),
        "the termination",
    )
    .await;
}

