#[tokio::test]
async fn a_server_certificate_above_the_size_limit_is_refused_by_the_client() {
    let client_events = Arc::new(Recorder::default());
    let server_events = Arc::new(Recorder::default());
    let station = start_station_with(&server_events, BIG_SERVER_CERTIFICATE, BIG_SERVER_KEY).await;
    let client = backend(&client_events, CLIENT_CERTIFICATE, CLIENT_KEY, crl(), true);
    let _ = connect_once(station, client).await;
    assert!(raised(&client_events, SecurityEvent::CertificateSizeExceeded).await);
}

/// A station with a given identity, in place of the test server certificate.
async fn start_station_with(events: &Arc<Recorder>, certificate: &[u8], key: &[u8]) -> SocketAddr {
    let config = ServerConfig::new(
        "127.0.0.1:0".parse().expect("an address"),
        CommonAddress::new(STATION),
    )
    .with_tls(backend(events, certificate, key, crl(), true));
    let server = Server::bind(config, Refuse).await.expect("binds");
    let local = server.local_addr().expect("an address");
    tokio::spawn(server.run());
    local
}

/// Connects a client station once and reports whether the session was established, without
/// waiting for a Started event: a refused handshake shows as a failed connection.
async fn connect_once(address: SocketAddr, backend: Secure) -> Result<(), String> {
    let config =
        ClientConfig::new(address, CommonAddress::new(STATION)).with_tls(backend, "localhost");
    let mut client = Client::connect(config);
    let outcome = timeout(Duration::from_secs(5), async {
        loop {
            match client.next_event().await {
                Some(Event::Connected) => {
                    if let Err(error) = client.start_data_transfer().await {
                        return Err(error.to_string());
                    }
                }
                Some(Event::Delivery(Delivery::Transfer(TransferState::Started))) => {
                    return Ok(());
                }
                Some(Event::ConnectFailed(error)) | Some(Event::Disconnected(error)) => {
                    return Err(error.to_string());
                }
                Some(_) => continue,
                None => return Err("the client stopped".to_string()),
            }
        }
    })
    .await;
    match outcome {
        Ok(result) => result,
        Err(_) => Err("no outcome within 5 s".to_string()),
    }
}

#[tokio::test]
async fn the_suites_that_rustls_cannot_offer_are_negotiated() {
    // The static RSA suite needs an RSA key in the station; table 9 lists it as mandatory.
    let server_events = Arc::new(Recorder::default());
    let station = start_station_with(&server_events, RSA_SERVER_CERTIFICATE, RSA_SERVER_KEY).await;
    let (name, _) = raw_client(station, |builder| {
        with_client_identity(builder);
        builder
            .set_max_proto_version(Some(SslVersion::TLS1_2))
            .expect("TLS 1.2");
        builder.set_cipher_list("AES128-SHA256").expect("the suite");
    })
    .await
    .expect("the CBC suite is negotiated");
    assert_eq!(name, "TLS_RSA_WITH_AES_128_CBC_SHA256");

    // The DHE-RSA suite, which also needs the RSA key (table 9).
    let (name, _) = raw_client(station, |builder| {
        with_client_identity(builder);
        builder
            .set_max_proto_version(Some(SslVersion::TLS1_2))
            .expect("TLS 1.2");
        builder.set_groups_list("ffdhe2048").expect("the group");
        builder
            .set_cipher_list("DHE-RSA-AES128-GCM-SHA256")
            .expect("the suite");
    })
    .await
    .expect("the DHE suite is negotiated");
    assert_eq!(name, "TLS_DHE_RSA_WITH_AES_128_GCM_SHA256");

    // The mandatory CCM suite of TLS 1.3 (table 13), offered alone.
    let station = start_station(&server_events, true).await;
    let (name, _) = raw_client(station, |builder| {
        with_client_identity(builder);
        builder
            .set_min_proto_version(Some(SslVersion::TLS1_3))
            .expect("TLS 1.3");
        builder
            .set_ciphersuites("TLS_AES_128_CCM_SHA256")
            .expect("the suite");
    })
    .await
    .expect("the CCM suite is negotiated");
    assert_eq!(name, "TLS_AES_128_CCM_SHA256");
}

#[tokio::test]
async fn the_mandatory_ffdhe_group_of_tls_13_is_negotiated() {
    // The mandatory group ffdhe2048 of TLS 1.3 (table 16), offered alone (clause 8.3.3).
    let server_events = Arc::new(Recorder::default());
    let station = start_station(&server_events, true).await;
    let (name, version) = raw_client(station, |builder| {
        with_client_identity(builder);
        builder
            .set_min_proto_version(Some(SslVersion::TLS1_3))
            .expect("TLS 1.3");
        builder.set_groups_list("ffdhe2048").expect("the group");
    })
    .await
    .expect("the handshake succeeds with ffdhe2048");
    assert!(name.starts_with("TLS_"), "a TLS 1.3 suite: {name}");
    assert_eq!(version.as_deref(), Some("TLSv1.3"));
}

/// The station key that an item of the profile needs.
#[derive(Clone, Copy)]
enum Key {
    /// The ECDSA key of the server certificate.
    Ecdsa,
    /// The RSA key of the RSA server certificate.
    Rsa,
    /// The RSA-PSS key of the PSS server certificate.
    Pss,
}

/// The mandatory TLS 1.2 suites (table 9 of clause 10.5.1): the profile name, the OpenSSL name, the
/// station key and the group that the test offers.
const TLS12_ITEMS: &[(&str, &str, Key, &str)] = &[
    (
        "TLS_RSA_WITH_AES_128_CBC_SHA256",
        "AES128-SHA256",
        Key::Rsa,
        "P-256",
    ),
    (
        "TLS_DHE_RSA_WITH_AES_128_GCM_SHA256",
        "DHE-RSA-AES128-GCM-SHA256",
        Key::Rsa,
        "ffdhe2048",
    ),
    (
        "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
        "ECDHE-RSA-AES128-GCM-SHA256",
        Key::Rsa,
        "P-256",
    ),
    (
        "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
        "ECDHE-ECDSA-AES128-GCM-SHA256",
        Key::Ecdsa,
        "P-256",
    ),
];

/// The mandatory TLS 1.3 suites (table 13 of clause 10.6.1), by their names, which OpenSSL shares.
const TLS13_ITEMS: &[&str] = &[
    "TLS_AES_128_GCM_SHA256",
    "TLS_AES_256_GCM_SHA384",
    "TLS_AES_128_CCM_SHA256",
];

/// The mandatory groups (table 16 of clause 10.6.2): the profile name and the OpenSSL name.
const GROUP_ITEMS: &[(&str, &str)] = &[("secp256r1", "P-256"), ("ffdhe2048", "ffdhe2048")];

/// The mandatory signature algorithms (tables 17 and 18 of clause 10.6.2): the profile name, the
/// list the client offers with its own ECDSA scheme (the client certificate is an ECDSA key), and
/// the station key. The scheme is the only one the station's key can use, so the handshake shows
/// that the station signs with it.
const SIGALG_ITEMS: &[(&str, &str, Key)] = &[
    (
        "rsa_pss_rsae_sha256",
        "rsa_pss_rsae_sha256:ecdsa_secp256r1_sha256",
        Key::Rsa,
    ),
    (
        "rsa_pss_pss_sha256",
        "rsa_pss_pss_sha256:ecdsa_secp256r1_sha256",
        Key::Pss,
    ),
    (
        "ecdsa_secp256r1_sha256",
        "ecdsa_secp256r1_sha256",
        Key::Ecdsa,
    ),
];

/// The mandatory signature algorithms that no test negotiates. rsa_pkcs1_sha256 is mandatory for
/// certificates (table 18): it needs a chain whose issuer signs with RSA PKCS#1, and the test root
/// is an ECDSA key. The test checks this list, so that it changes only with the test.
const NOT_NEGOTIATED: &[&str] = &["rsa_pkcs1_sha256"];

#[tokio::test]
async fn every_mandatory_item_of_the_profile_is_negotiated() {
    // Each item is offered alone to a station with the key it needs. The client holds the test
    // client certificate, which the station requires (clause 6.4.3). An item without a row in the
    // tables above panics, so a new mandatory item cannot be left out.
    let events = Arc::new(Recorder::default());
    let ecdsa = start_station_with(&events, SERVER_CERTIFICATE, SERVER_KEY).await;
    let rsa = start_station_with(&events, RSA_SERVER_CERTIFICATE, RSA_SERVER_KEY).await;
    let pss = start_station_with(&events, PSS_SERVER_CERTIFICATE, PSS_SERVER_KEY).await;
    let station = |key: Key| match key {
        Key::Ecdsa => ecdsa,
        Key::Rsa => rsa,
        Key::Pss => pss,
    };

    for suite in TLS12_SUITES
        .iter()
        .filter(|suite| suite.support == Support::Mandatory)
    {
        let Some(&(_, openssl, key, group)) = TLS12_ITEMS.iter().find(|item| item.0 == suite.name)
        else {
            panic!("no test for the mandatory TLS 1.2 suite {}", suite.name);
        };
        let (name, version) = raw_client(station(key), |builder| {
            with_client_identity(builder);
            builder
                .set_max_proto_version(Some(SslVersion::TLS1_2))
                .expect("TLS 1.2");
            builder.set_groups_list(group).expect("the group");
            builder.set_cipher_list(openssl).expect("the suite");
        })
        .await
        .unwrap_or_else(|error| panic!("{} is not negotiated: {error}", suite.name));
        assert_eq!(name, suite.name);
        assert_eq!(version.as_deref(), Some("TLSv1.2"));
    }

    for suite in TLS13_SUITES
        .iter()
        .filter(|suite| suite.support == Support::Mandatory)
    {
        assert!(
            TLS13_ITEMS.contains(&suite.name),
            "no test for the mandatory TLS 1.3 suite {}",
            suite.name
        );
        let (name, version) = raw_client(ecdsa, |builder| {
            with_client_identity(builder);
            builder
                .set_min_proto_version(Some(SslVersion::TLS1_3))
                .expect("TLS 1.3");
            builder.set_ciphersuites(suite.name).expect("the suite");
        })
        .await
        .unwrap_or_else(|error| panic!("{} is not negotiated: {error}", suite.name));
        assert_eq!(name, suite.name);
        assert_eq!(version.as_deref(), Some("TLSv1.3"));
    }

    for group in GROUPS
        .iter()
        .filter(|group| group.support == Support::Mandatory)
    {
        let Some(&(_, openssl)) = GROUP_ITEMS.iter().find(|item| item.0 == group.name) else {
            panic!("no test for the mandatory group {}", group.name);
        };
        let (_, version) = raw_client(ecdsa, |builder| {
            with_client_identity(builder);
            builder
                .set_min_proto_version(Some(SslVersion::TLS1_3))
                .expect("TLS 1.3");
            builder.set_groups_list(openssl).expect("the group");
        })
        .await
        .unwrap_or_else(|error| panic!("the group {} is not negotiated: {error}", group.name));
        assert_eq!(version.as_deref(), Some("TLSv1.3"));
    }

    let mut untested = Vec::new();
    for scheme in MANDATORY_SIGNATURE_ALGORITHMS {
        if NOT_NEGOTIATED.contains(&scheme.name) {
            untested.push(scheme.name);
            continue;
        }
        let Some(&(_, offered, key)) = SIGALG_ITEMS.iter().find(|item| item.0 == scheme.name)
        else {
            panic!(
                "no test for the mandatory signature algorithm {}",
                scheme.name
            );
        };
        let (_, version) = raw_client(station(key), |builder| {
            with_client_identity(builder);
            builder
                .set_min_proto_version(Some(SslVersion::TLS1_3))
                .expect("TLS 1.3");
            builder.set_sigalgs_list(offered).expect("the scheme");
        })
        .await
        .unwrap_or_else(|error| {
            panic!(
                "the signature algorithm {} is not negotiated: {error}",
                scheme.name
            )
        });
        assert_eq!(version.as_deref(), Some("TLSv1.3"));
    }
    assert_eq!(
        untested,
        ["rsa_pkcs1_sha256"],
        "the untested signature algorithms changed"
    );
}

/// The trust anchors of a test: the five roots, and the RSA test root when `with_rsa` is set.
fn roots(with_rsa: bool) -> Vec<Vec<u8>> {
    let mut roots = der_list(ROOTS);
    if with_rsa {
        roots.extend(der_list(RSA_CA));
    }
    roots
}

/// A station's TLS backend, with its identity, trust anchors, CRLs and the RSA policy of clause 7.4.3.
fn station_backend(
    events: &Arc<Recorder>,
    certificate: &[u8],
    key: &[u8],
    roots: Vec<Vec<u8>>,
    crls: Vec<Vec<u8>>,
    rsa_1024: bool,
) -> Secure {
    let (chain, key) = der_pair(certificate, key);
    let shared: Arc<dyn SecurityEvents> = events.clone();
    let identity = Identity::new(chain, key, events.as_ref()).expect("the identity");
    let trust = TrustAnchors::new(roots).expect("the roots");
    let settings = TlsSettings::new(identity, trust, shared)
        .with_revocation(crls)
        .with_tls13(true)
        .with_rsa_1024(rsa_1024);
    Secure::new(OpensslBackend::new(&settings).expect("the backend"))
}

/// Starts a station with the given backend, and returns its address.
async fn start_station_on(backend: Secure) -> SocketAddr {
    let config = ServerConfig::new(
        "127.0.0.1:0".parse().expect("an address"),
        CommonAddress::new(STATION),
    )
    .with_tls(backend);
    let server = Server::bind(config, Refuse).await.expect("binds");
    let local = server.local_addr().expect("an address");
    tokio::spawn(server.run());
    local
}

/// The configuration of a raw client that presents a certificate and its key, over TLS 1.2. The security
/// level lets it present a key below the level of OpenSSL's defaults, which the tests of clause 7.4.3 need.
fn present<'a>(
    certificate: &'a [u8],
    key: &'a [u8],
    security_level: u32,
) -> impl FnOnce(&mut openssl::ssl::SslConnectorBuilder) + 'a {
    move |builder| {
        // TLS 1.2: a TLS 1.3 client finishes before the server checks its certificate (Q-027), so a
        // refusal would not reach the client.
        builder
            .set_max_proto_version(Some(SslVersion::TLS1_2))
            .expect("TLS 1.2");
        builder.set_security_level(security_level);
        let certificate = X509::from_pem(certificate).expect("the certificate");
        builder
            .set_certificate(&certificate)
            .expect("the certificate");
        let key = openssl::pkey::PKey::private_key_from_pem(key).expect("the key");
        builder.set_private_key(&key).expect("the key");
    }
}

#[tokio::test]
async fn a_client_certificate_under_an_rsa_root_is_accepted_with_rsa_pkcs1() {
    // The chain of the client is signed with RSA PKCS#1 and SHA-256 (rsa_pkcs1_sha256, table 18).
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(true),
        Vec::new(),
        false,
    ))
    .await;
    raw_client(station, present(RSA_CLIENT_CERTIFICATE, RSA_CLIENT_KEY, 2))
        .await
        .expect("the handshake succeeds");
    assert!(raised(&events, SecurityEvent::TlsHandshakeSuccess).await);
}

#[tokio::test]
async fn the_lack_of_a_crl_of_the_issuer_is_a_warning_and_the_client_is_accepted() {
    // The station has a CRL, of the test root; the client's issuer is the RSA root, which has none.
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(true),
        vec![crl_der(CRL)],
        false,
    ))
    .await;
    raw_client(station, present(RSA_CLIENT_CERTIFICATE, RSA_CLIENT_KEY, 2))
        .await
        .expect("the handshake succeeds");
    assert!(raised(&events, SecurityEvent::NoCrl).await);
}

#[tokio::test]
async fn an_expired_crl_is_a_warning_and_the_client_is_accepted() {
    // The CRL of the issuer ended in 2020. Clause 6.4.4.4.2: a warning, and the session goes on.
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        vec![crl_der(EXPIRED_CRL)],
        false,
    ))
    .await;
    raw_client(station, with_client_identity)
        .await
        .expect("the handshake succeeds");
    assert!(raised(&events, SecurityEvent::CrlExpired).await);
}

#[tokio::test]
async fn a_certificate_whose_signature_does_not_verify_is_refused_with_the_alarm() {
    // The certificate of the client, with one bit of its signature changed: it does not verify.
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        false,
    ))
    .await;
    assert!(
        raw_client(station, present(TAMPERED_CLIENT_CERTIFICATE, CLIENT_KEY, 2))
            .await
            .is_err()
    );
    assert!(raised(&events, SecurityEvent::SignatureNotVerified).await);
}

#[tokio::test]
async fn a_certificate_signed_with_sha_1_is_refused_with_the_warning() {
    // Clause 7.4.3: the detection of SHA-1 raises the warning; the policy refuses the certificate (D-018).
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        false,
    ))
    .await;
    assert!(raw_client(
        station,
        present(SHA1_CLIENT_CERTIFICATE, SHA1_CLIENT_KEY, 0)
    )
    .await
    .is_err());
    assert!(raised(&events, SecurityEvent::DeprecatedHash).await);
}

#[tokio::test]
async fn an_rsa_key_of_1024_bits_is_refused_unless_the_policy_allows_it() {
    // Clause 7.4.3: with the 1 024-bit keys disabled, a key below 2 048 bits raises the alarm and
    // is refused.
    let refusing = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &refusing,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        false,
    ))
    .await;
    assert!(raw_client(
        station,
        present(RSA1024_CLIENT_CERTIFICATE, RSA1024_CLIENT_KEY, 0)
    )
    .await
    .is_err());
    assert!(raised(&refusing, SecurityEvent::ShortRsaKey).await);

    // With the policy allowing them, the warning is raised, and the client is accepted.
    let allowing = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &allowing,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        true,
    ))
    .await;
    raw_client(
        station,
        present(RSA1024_CLIENT_CERTIFICATE, RSA1024_CLIENT_KEY, 0),
    )
    .await
    .expect("the handshake succeeds");
    assert!(raised(&allowing, SecurityEvent::MinimumKeyLength).await);
}

#[tokio::test]
async fn an_rsa_key_below_1024_bits_is_refused_even_when_the_policy_allows_1024() {
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        true,
    ))
    .await;
    assert!(raw_client(
        station,
        present(RSA512_CLIENT_CERTIFICATE, RSA512_CLIENT_KEY, 0)
    )
    .await
    .is_err());
    assert!(raised(&events, SecurityEvent::ShortKey).await);
    assert!(raised(&events, SecurityEvent::ShortRsaKey).await);
}

#[tokio::test]
async fn a_peer_with_no_signature_algorithm_in_common_is_refused_with_the_alarm() {
    // The peer offers only ECDSA with P-384 and SHA-384: the station's keys cannot sign for it.
    let events = Arc::new(Recorder::default());
    let station = start_station_on(station_backend(
        &events,
        SERVER_CERTIFICATE,
        SERVER_KEY,
        roots(false),
        Vec::new(),
        false,
    ))
    .await;
    let outcome = raw_client(station, |builder| {
        builder
            .set_sigalgs_list("ecdsa_secp384r1_sha384")
            .expect("the scheme");
    })
    .await;
    assert!(outcome.is_err(), "the handshake fails");
    assert!(raised(&events, SecurityEvent::SignatureAlgorithmNotSupported).await);
}

/// The DER of the first CRL in a PEM file.
fn crl_der(pem: &[u8]) -> Vec<u8> {
    openssl::x509::X509Crl::from_pem(pem)
        .expect("a CRL")
        .to_der()
        .expect("DER")
}
